function model(p) {
  // Illustrative self-attention for one sentence, two variants (last word "tired" or "wide") and two heads.
  // Scores are hand-set compatibilities, not weights from a real model; each row goes through a softmax.
  const LAST = ['tired', 'wide'], HEADS = ['Meaning head', 'Position head'];
  const base = ['The', 'cat', "didn't", 'cross', 'the', 'road', 'because', 'it', 'was', 'too'];
  const v = Math.round(Math.min(1, Math.max(0, p.lastWord)));
  const h = Math.round(Math.min(1, Math.max(0, p.head)));
  const fIdx = [7, 10, 3][Math.round(Math.min(2, Math.max(0, p.focus)))];
  const softmax = xs => { const mx = Math.max(...xs), e = xs.map(x => Math.exp(x - mx)), s = e.reduce((a, b) => a + b, 0); return e.map(x => x / s); };
  // Meaning head: what each word "looks for". tired describes an animal (cat), wide describes a place (road).
  function meaning(last) {
    const tired = last === 'tired', n = 11, S = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 0.5 : 0)));
    const set = (i, pairs) => { for (const j in pairs) S[i][j] = pairs[j]; };
    set(0, { 1: 2.5 });                                   // The -> its noun
    set(1, { 2: 1.2, 3: 1.8, 7: tired ? 1.0 : 0.2, 10: tired ? 1.6 : 0.3 }); // cat -> what it does, what describes it
    set(2, { 1: 1.2, 3: 2.4 });                           // didn't -> the verb it negates
    set(3, { 1: 2.0, 2: 1.4, 5: 2.2 });                   // cross -> who crosses, what is crossed
    set(4, { 5: 2.5 });                                   // the -> its noun
    set(5, { 3: 2.0, 4: 0.8, 7: tired ? 0.2 : 1.0, 10: tired ? 0.2 : 1.6 });
    set(6, { 2: 1.4, 3: 1.2, 8: 1.0, 10: 1.2 });          // because -> the two clauses it joins
    set(7, { 1: tired ? 3.0 : 0.6, 5: tired ? 0.6 : 3.0, 8: 0.6, 10: 1.6 }); // it -> the noun the adjective fits
    set(8, { 7: 2.0, 10: 1.6 });                          // was -> subject and complement
    set(9, { 10: 2.6 });                                  // too -> the adjective it modifies
    set(10, { 1: tired ? 2.0 : 0, 5: tired ? 0 : 2.0, 7: 2.2, 9: 1.2 }); // last word -> what it describes
    return S;
  }
  // Position head: ignores meaning. Strong recency bias: the previous word, then the next word, then distance decay.
  function position() {
    return Array.from({ length: 11 }, (_, i) => Array.from({ length: 11 }, (_, j) => {
      const d = j - i;
      return d === 0 ? 0.8 : d === -1 ? 2.4 : d === 1 ? 2.0 : 0.6 - 0.5 * (Math.abs(d) - 2);
    }));
  }
  const build = S => S.map(softmax);
  const matrices = {};
  LAST.forEach(w => { matrices[w] = { meaning: build(meaning(w)), position: build(position()) }; });
  const last = LAST[v], words = base.concat([last]);
  const matrix = matrices[last][h ? 'position' : 'meaning'];
  const row = matrix[fIdx];
  const tokens = words.map((text, i) => ({ i, text, weight: row[i], isFocus: i === fIdx }));
  const others = tokens.filter(t => !t.isFocus).sort((a, b) => b.weight - a.weight || a.i - b.i);
  const top3 = others.slice(0, 3).map(t => t.i), strongest = others[0];
  tokens.forEach(t => { t.rank = t.isFocus ? 0 : others.indexOf(t) + 1; t.top3 = top3.includes(t.i); t.strongest = t.i === strongest.i; });
  // The referent of "it" according to the meaning head: what the sentence means.
  const itRow = matrices[last].meaning[7], referent = itRow[1] > itRow[5] ? 'cat' : 'road';
  const pc = x => Math.round(x * 100) + '%', f = words[fIdx], s = strongest.text;
  let why;
  if (h) why = 'the word right ' + (strongest.i < fIdx ? 'before' : 'after') + ' it. This head tracks position, not meaning.';
  else if (fIdx === 7) why = 'so "it" means the ' + s + ': ' + (last === 'tired' ? 'cats get tired.' : 'roads are wide.');
  else if (fIdx === 10) why = 'and ' + pc(row[referent === 'cat' ? 1 : 5]) + ' on "' + referent + '": the thing that was too ' + last + '.';
  else why = 'and ' + pc(others[1].weight) + ' on "' + others[1].text + '": what is crossed and who crosses.';
  const summary = '"' + f + '" puts ' + pc(strongest.weight) + ' of its attention on "' + s + '", ' + why;
  const steps = [
    { at: 0, label: 'Read the sentence' },
    { at: 1.5, label: 'Pick the focus word' },
    { at: 3, label: 'Its attention weights appear' },
    { at: 6.5, label: 'The strongest link' },
    { at: 8.5, label: 'What it means' }
  ];
  return {
    words, tokens, lastWord: last, head: HEADS[h], headIndex: h, focusIndex: fIdx, focusWord: f,
    matrix, row, selfWeight: row[fIdx], rowSum: row.reduce((a, b) => a + b, 0),
    strongest: { i: strongest.i, text: s, weight: strongest.weight }, top3, referent, matrices,
    steps, duration: 10, markers: steps.map(x => x.at), summary
  };
}

checkCode:
function check(p) {
  const m = model(p), all = [];
  for (const w in m.matrices) for (const k in m.matrices[w]) all.push(m.matrices[w][k]);
  const worst = Math.max(...all.flatMap(M => M.map(r => Math.abs(r.reduce((a, b) => a + b, 0) - 1))));
  const argmax = r => r.reduce((b, x, j) => (x > r[b] ? j : b), 0);
  const itT = m.matrices.tired.meaning[7], itW = m.matrices.wide.meaning[7];
  const tiredOk = argmax(itT) === 1, wideOk = argmax(itW) === 5;
  const posOk = ['tired', 'wide'].every(w => m.matrices[w].position.every((r, i) => Math.abs(argmax(r) - i) === 1));
  const pc = x => Math.round(x * 100) + '%';
  return {
    pass: worst < 1e-9 && tiredOk && wideOk && posOk && Math.abs(m.rowSum - 1) < 1e-9,
    detail: 'All 44 rows sum to 1 (largest error ' + worst.toExponential(1) + '); the meaning head sends "it" ' + pc(itT[1]) + ' to "cat" with "tired" and ' +
      pc(itW[5]) + ' to "road" with "wide"; the position head\'s strongest link is to an adjacent word in ' + (posOk ? 'all 22' : 'not all 22') + ' rows.'
  };
}
